/*
 * Synthetic boundary test for the CVE-2017-10663 guard added to
 * fs/f2fs/super.c:sanity_check_ckpt(). It mirrors the exact condition
 * structure and integer widths (__le32 segno, __le16 blkoff) of the
 * candidate patch. This is NOT a kernel build; it only exercises the
 * boundary logic with the available gcc-8.
 */
#include <stdio.h>
#include <assert.h>

typedef unsigned int u32;
typedef unsigned short u16;

#define NR_CURSEG_NODE_TYPE 3
#define NR_CURSEG_DATA_TYPE 3

static int guard(u32 main_segs, u32 blocks_per_seg,
                 const u32 *ns, const u16 *nb,
                 const u32 *ds, const u16 *db)
{
    int i;
    for (i = 0; i < NR_CURSEG_NODE_TYPE; i++) {
        if (ns[i] >= main_segs || nb[i] >= blocks_per_seg)
            return 1;
    }
    for (i = 0; i < NR_CURSEG_DATA_TYPE; i++) {
        if (ds[i] >= main_segs || db[i] >= blocks_per_seg)
            return 1;
    }
    return 0;
}

int main(void)
{
    const u32 main_segs = 100;
    const u32 blocks_per_seg = 512;

    /* positive: all values in range -> accept (0) */
    u32 ns[3] = {0, 50, 99};
    u16 nb[3] = {0, 1, 511};
    u32 ds[3] = {0, 50, 99};
    u16 db[3] = {0, 1, 511};
    assert(guard(main_segs, blocks_per_seg, ns, nb, ds, db) == 0);
    printf("positive in-range: accept\n");

    /* negative: node segno == main_segs -> reject */
    ns[1] = 100; assert(guard(main_segs, blocks_per_seg, ns, nb, ds, db) == 1);
    ns[1] = 50;
    /* negative: node blkoff == blocks_per_seg -> reject */
    nb[2] = 512; assert(guard(main_segs, blocks_per_seg, ns, nb, ds, db) == 1);
    nb[2] = 511;
    /* negative: data segno == main_segs -> reject */
    ds[0] = 100; assert(guard(main_segs, blocks_per_seg, ns, nb, ds, db) == 1);
    ds[0] = 0;
    /* negative: data blkoff == blocks_per_seg -> reject */
    db[1] = 512; assert(guard(main_segs, blocks_per_seg, ns, nb, ds, db) == 1);
    db[1] = 1;

    /* sanity: guard restored */
    assert(guard(main_segs, blocks_per_seg, ns, nb, ds, db) == 0);
    printf("negative out-of-range: reject (segno==main_segs, blkoff==blocks_per_seg)\n");
    printf("ALL BOUNDARY ASSERTIONS PASSED\n");
    return 0;
}

